<?php
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['save_change'])){$st=$pdo->prepare("INSERT INTO change_orders(contract_id,change_no,title,reason,value_delta,status) VALUES(?,?,?,?,?,?)");$st->execute([$_POST['contract_id']?:null,trim($_POST['change_no']),trim($_POST['title']),trim($_POST['reason']),$_POST['value_delta']?:0,$_POST['status']]);header('Location:index.php?page=change_order');exit;}
$contractsList=$pdo->query("SELECT id,contract_no,title FROM contracts ORDER BY id DESC")->fetchAll();$rows=$pdo->query("SELECT co.*,c.contract_no FROM change_orders co LEFT JOIN contracts c ON c.id=co.contract_id ORDER BY co.id DESC")->fetchAll();
?><div class="page-head"><div><h1>Change Order</h1><p>Kelola perubahan scope, value, dan ketentuan kontrak secara terkontrol.</p></div><button class="btn btn-primary" data-bs-toggle="modal" data-bs-target="#changeModal"><i class="bi bi-plus-lg me-1"></i> New Change Order</button></div><div class="card p-3"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Change No.</th><th>Contract</th><th>Change</th><th>Value Delta</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?=de($r['change_no'])?></strong></td><td><?=de($r['contract_no']?:'-')?></td><td><?=de($r['title'])?><small class="d-block text-muted"><?=de($r['reason']?:'')?></small></td><td>Rp <?=number_format((float)$r['value_delta'],0,',','.')?></td><td><span class="status-pill <?=strtolower(str_replace(' ','-',$r['status']))?>"><?=de($r['status'])?></span></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="5" class="text-center text-muted py-5">Belum ada change order.</td></tr><?php endif;?></tbody></table></div></div>
<div class="modal fade" id="changeModal"><div class="modal-dialog"><form method="post" class="modal-content"><div class="modal-header"><h5 class="fw-bold">New Change Order</h5><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><div class="row g-3"><div class="col-5"><label class="form-label">Change No.</label><input class="form-control" name="change_no" value="CO-<?=date('YmdHis')?>" required></div><div class="col-7"><label class="form-label">Contract</label><select class="form-select" name="contract_id"><option value="">Pilih contract</option><?php foreach($contractsList as $c):?><option value="<?=$c['id']?>"><?=de($c['contract_no'].' — '.$c['title'])?></option><?php endforeach;?></select></div></div><label class="form-label mt-3">Change Title</label><input class="form-control" name="title" required><label class="form-label mt-3">Reason</label><textarea class="form-control" name="reason" rows="3"></textarea><div class="row g-3 mt-1"><div class="col-6"><label class="form-label">Value Delta</label><input type="number" class="form-control" name="value_delta" value="0"></div><div class="col-6"><label class="form-label">Status</label><select class="form-select" name="status"><option>Draft</option><option>Pending Approval</option><option>Approved</option><option>Rejected</option></select></div></div></div><div class="modal-footer"><button class="btn btn-primary" name="save_change">Save Change Order</button></div></form></div></div>
